#include "stdafx.h"#include "NumEdit.h"// KNumEditIMPLEMENT_DYNAMIC(KNumEdit, CEdit)KNumEdit::KNumEdit(){}KNumEdit::~KNumEdit(){}BEGIN_MESSAGE_MAP(KNumEdit, CEdit)  ON_WM_CHAR()END_MESSAGE_MAP()// KNumEdit message handlersvoid KNumEdit::OnChar(UINT nChar, UINT nRepCnt, UINT nFlags){  if( VK_RETURN==nChar )  {    static MEN_KEYDOWN_NOTIFY mkn;    mkn.nmhdr.hwndFrom = GetSafeHwnd();    mkn.nmhdr.idFrom   = GetDlgCtrlID();    mkn.nmhdr.code     = MEN_KEYDOWN;    mkn.nChar          = nChar;    mkn.nFlags         = nFlags;    GetParent()->SendMessage(WM_NOTIFY,mkn.nmhdr.idFrom,(LPARAM)&mkn);    return;  }  CEdit::OnChar(nChar, nRepCnt, nFlags);}